draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);

  // book
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 4;
  ctx.fillStyle = '#dfd6c5';
  ctx.beginPath();
  ctx.rect(W/2-50, H/2-50, 100, 100);
  ctx.fill();
  ctx.stroke();

  // stick figure
  ctx.strokeStyle = 'black';
  ctx.lineWidth = 3;
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2-120, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-100);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-70);
  ctx.lineTo(W/2-30, H/2-30);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-70);
  ctx.lineTo(W/2+30, H/2-30);
  ctx.stroke();

  // wisdom lesson
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Wisdom', W/2, H/2-180 + 20 * Math.sin(t));

  // life applying
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('Apply to Life', W/2, H/2-20 + 20 * Math.cos(t));

  ctx.restore();
}
